      --track-research: #1e3a5f;
      --track-industry: #d4a73a;
      --track-regulation: #881337; /* Cranberry/Rose for regulation */
      --investment-fill: rgba(212, 167, 58, 0.15);
      --investment-line: #d4a73a;
    }

    * { box-sizing: border-box; margin: 0; padding: 0; }

    body {
      font-family: var(--font-body);
      background-color: var(--bg);
      color: var(--text);
      line-height: 1.6;
      padding: 40px;
    }

    .container {
      max-width: 1200px;
      margin: 0 auto;
    }

    .header {
      margin-bottom: 40px;
      text-align: left;
    }

    h1 {
      font-family: var(--font-heading);
      font-size: 3.5rem;
      font-weight: 400;
      color: var(--text);
      line-height: 1.1;
      margin-bottom: 16px;
    }

    .lead {
      font-family: var(--font-body);
      font-size: 1.1rem;
      color: var(--text-dim);
      max-width: 800px;
    }

    .metrics-row {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 20px;
      margin-bottom: 40px;
    }

    .metric-card {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 8px;
      padding: 24px;
      box-shadow: 0 4px 12px rgba(30, 58, 95, 0.03);
    }

    .metric-label {
      font-size: 0.85rem;
      text-transform: uppercase;
      letter-spacing: 0.05em;
      color: var(--text-dim);
      margin-bottom: 8px;
    }

    .metric-value {
      font-family: var(--font-heading);
      font-size: 2.5rem;
      color: var(--track-industry);
    }

    .chart-container {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 12px;
      padding: 30px;
      box-shadow: 0 8px 24px rgba(30, 58, 95, 0.04);
      position: relative;
      height: 600px;
    }

    .legend-custom {
      display: flex;
      gap: 24px;
      justify-content: center;
      margin-top: 20px;
      font-size: 0.9rem;
    }

    .legend-item {
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .legend-color {
      width: 12px;
      height: 12px;
      border-radius: 50%;
