      <div class="legend-item"><div class="legend-color" style="background: var(--track-industry)"></div> Industry</div>
      <div class="legend-item"><div class="legend-color" style="background: var(--track-regulation)"></div> Regulation</div>
      <div class="legend-item"><div class="legend-color" style="background: var(--investment-line)"></div> Private Investment ($B)</div>
