        <strong>Density Acceleration:</strong> There are more milestone events clustered in 2023-2024 across all three tracks than in the entire 2010-2017 period combined.
      </div>
      <div class="insight-card">
        <strong>Capital Catalyst:</strong> The inflection point triggered a massive capital influx. Private investment doubled from $48.2B in 2022 to $95.8B in 2024 following the launch of ChatGPT.
      </div>
    </div>
  </div>

  <script>
    // Prepare data
    const parseDate = (dateStr) => {
      if (dateStr.length === 4) return parseInt(dateStr) + 0.5;
      const parts = dateStr.split('-');
      return parseInt(parts[0]) + (parseInt(parts[1]) - 1) / 12;
    };

    const researchMilestones = RAW_RESEARCH;
    const industryMilestones = RAW_INDUSTRY;
    const regulationMilestones = RAW_REGULATION;
    const investmentData = RAW_INVESTMENT;

    const getRadius = (sig) => sig === 'critical' ? 12 : sig === 'high' ? 8 : 5;

    const researchPoints = researchMilestones.map(d => ({ x: parseDate(d.date), y: 3, r: getRadius(d.significance), label: d.label }));
    const industryPoints = industryMilestones.map(d => ({ x: parseDate(d.date), y: 2, r: getRadius(d.significance), label: d.label }));
    const regulationPoints = regulationMilestones.map(d => ({ x: parseDate(d.date), y: 1, r: getRadius(d.significance), label: d.label }));

    const investmentPoints = investmentData.map(d => ({ x: d.year + 0.5, y: d.investment }));

