            type: 'line',
            label: 'Private Investment ($B)',
            data: investmentPoints,
            yAxisID: 'yInvestment',
            borderColor: investmentLine,
            backgroundColor: investmentFill,
            borderWidth: 2,
            fill: true,
            tension: 0.4,
            pointRadius: 0,
            pointHoverRadius: 0
          },
          {
            label: 'Research',
            data: researchPoints,
            yAxisID: 'yTracks',
            backgroundColor: trackResearch,
            borderColor: 'rgba(255,255,255,0.8)',
            borderWidth: 1
          },
          {
            label: 'Industry',
            data: industryPoints,
            yAxisID: 'yTracks',
            backgroundColor: trackIndustry,
            borderColor: 'rgba(255,255,255,0.8)',
            borderWidth: 1
          },
          {
            label: 'Regulation',
            data: regulationPoints,
            yAxisID: 'yTracks',
            backgroundColor: trackRegulation,
            borderColor: 'rgba(255,255,255,0.8)',
            borderWidth: 1
          }
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        layout: {
          padding: { top: 20, right: 20, bottom: 20, left: 0 }
        },
        plugins: {
          legend: { display: false },
          tooltip: {
            callbacks: {
              label: function(context) {
                if (context.dataset.type === 'line') return ` Investment: $${context.raw.y}B`;
                return ` ${context.raw.label} (${context.raw.x.toFixed(1)})`;
              }
            }
          },
          annotation: {
            annotations: {
              line1: {
                type: 'line',
                xMin: parseDate('2022-11'),
                xMax: parseDate('2022-11'),
                borderColor: 'rgba(212, 167, 58, 0.5)',
                borderWidth: 2,
                borderDash: [5, 5],
                label: {
                  content: 'ChatGPT Inflection',
                  display: true,
                  position: 'start',
                  yAdjust: 10
                }
              }
            }
          }
        },
        scales: {
          x: {
            type: 'linear',
            position: 'bottom',
            min: 2009.5,
            max: 2025.5,
            grid: {
              color: 'rgba(30, 58, 95, 0.05)',
              drawBorder: false
            },
            ticks: {
              stepSize: 1,
              callback: function(value) { return Math.floor(value); }
            }
          },
          yTracks: {
            type: 'linear',
            position: 'left',
            min: 0.5,
            max: 3.5,
            grid: {
              color: 'rgba(30, 58, 95, 0.05)',
              drawBorder: false
            },
            ticks: {
              stepSize: 1,
              callback: function(value) {
                if (value === 3) return 'Research';
                if (value === 2) return 'Industry';
                if (value === 1) return 'Regulation';
                return '';
              },
              font: {
                family: "'Instrument Serif', serif",
                size: 18
              },
              color: '#1e3a5f'
            }
          },
          yInvestment: {
            type: 'linear',
            position: 'right',
            min: 0,
            max: 150,
            grid: {
              drawOnChartArea: false
            },
            title: {
              display: true,
              text: 'Investment (Billions USD)',
              font: {
                family: "'JetBrains Mono', monospace",
                size: 11
              }
            }
          }
        }
      }
    });
  </script>
</body>
</html>"""

html_content = html_content.replace('RAW_RESEARCH', json.dumps(data['research_milestones']['data']))
