        const yTop = chart.chartArea.top;
        const yBottom = chart.chartArea.bottom;
        const c = chart.ctx;
        c.save();
        c.beginPath();
        c.setLineDash([5, 5]);
        c.moveTo(xPos, yTop);
        c.lineTo(xPos, yBottom);
        c.lineWidth = 2;
        c.strokeStyle = 'rgba(212, 167, 58, 0.8)';
        c.stroke();

        c.fillStyle = 'rgba(212, 167, 58, 1)';
        c.font = "bold 12px 'JetBrains Mono'";
        c.fillText("ChatGPT Inflection", xPos - 140, yTop + 20);
        c.fillText("(Nov 2022)", xPos - 140, yTop + 36);
        c.restore();
      }
    };

    new Chart(ctx, {
      type: 'bubble',
      data: {
        datasets: [
          {
            type: 'line',
            label: 'Private Investment ($B)',
            data: investmentPoints,
            yAxisID: 'yInvestment',
            borderColor: '#d4a73a',
            backgroundColor: 'rgba(212, 167, 58, 0.15)',
            borderWidth: 3,
            fill: true,
            tension: 0.4,
            pointRadius: 0,
