            label: 'Regulation',
            data: regulationPoints,
            yAxisID: 'yTracks',
            backgroundColor: '#881337',
            borderColor: 'rgba(255,255,255,0.9)',
            borderWidth: 1.5,
            order: 3
          }
        ]
      },
      plugins: [inflectionPlugin],
      options: {
        animation: false,
        responsive: true,
        maintainAspectRatio: false,
        layout: {
          padding: { top: 20, right: 20, bottom: 20, left: 0 }
        },
        plugins: {
          legend: { display: false }
        },
        scales: {
          x: {
            type: 'linear',
            position: 'bottom',
            min: 2009.5,
            max: 2025.5,
            grid: {
              color: 'rgba(30, 58, 95, 0.05)',
              drawBorder: false
            },
            ticks: {
              stepSize: 1,
              callback: function(value) { return Math.floor(value); }
            }
          },
          yTracks: {
            type: 'linear',
            position: 'left',
            min: 0.5,
            max: 3.5,
            grid: {
              color: 'rgba(30, 58, 95, 0.05)',
              drawBorder: false
            },
            ticks: {
              stepSize: 1,
              callback: function(value) {
                if (value === 3) return 'Research';
                if (value === 2) return 'Industry';
                if (value === 1) return 'Regulation';
                return '';
              },
              font: {
